package ec.espe.facturacion;
import ec.espe.facturacion.application.*; import ec.espe.facturacion.adapters.in.*; import ec.espe.facturacion.adapters.out.*; import java.math.BigDecimal;
public class Main { public static void main(String[] args)throws Exception {String mode=System.getenv().getOrDefault("DB_MODE","memory");InvoiceRepository repo;if(mode.equalsIgnoreCase("postgres")||mode.equalsIgnoreCase("oracle")){String url=required("DB_URL"),user=required("DB_USER"),password=System.getenv().getOrDefault("DB_PASSWORD","");repo=new JdbcInvoiceRepository(new DriverManagerDataSource(url,user,password));}else repo=new InMemoryInvoiceRepository();var useCase=new CreateInvoiceUseCase(repo,new BigDecimal(System.getenv().getOrDefault("TAX_RATE","0.15")),new BigDecimal(System.getenv().getOrDefault("REVIEW_THRESHOLD","1000")));var service=new InvoiceService(useCase);new RestAdapter(service).start(Integer.parseInt(System.getenv().getOrDefault("REST_PORT","8080")));String uri=System.getenv("AMQP_URI");if(uri!=null&&!uri.isBlank())new AmqpAdapter(service).start(uri,System.getenv().getOrDefault("AMQP_QUEUE","invoices.create"));}private static String required(String k){String v=System.getenv(k);if(v==null||v.isBlank())throw new IllegalStateException("Falta variable de entorno "+k);return v;}}
